import re
p = 'docs/numbers.md'
lines = open(p).read().split('\n')
def row(start, new):
    k = [i for i, l in enumerate(lines) if l.startswith(start)]
    assert len(k) == 1, (start, len(k))
    lines[k[0]] = new
def tweak(start, a, b):
    k = [i for i, l in enumerate(lines) if l.startswith(start)]
    assert len(k) == 1, (start, len(k))
    assert lines[k[0]].count(a) == 1, (start, a)
    lines[k[0]] = lines[k[0]].replace(a, b)

tweak('| `TYPICAL_RUNOFF` (8.5e-9', "the stand-in discharge per m² drained where a number that never changes needs one (the bends of a drawn channel, which channels a tile holds as lines; drawing only)",
      "the stand-in discharge per m² drained where a number that never changes needs one (a drawn channel's bed, `BED_RUNOFF`; which channels a tile holds as lines; drawing only)")
tweak('| `TYPICAL_RUNOFF` (8.5e-9', "; the 22 island of seed 1 passes on about 5 times more", "; the main river of the 22 island of seed 1 passes on about as much in its twelfth year (0.54 m³/s from 67 km²)")
row('| `LINE_PX` (1.2), `LINE_MOST`', "| `LINE_PX` (1.2), `LINE_MOST` (4), `LINE_GROW` (0.75), `LINE_FADE` (4), `web/shaders/land.wgsl` | css pixels; none; none; none | a channel past the discharge that shows is a line at least this wide, wider as its discharge over that grows to the power `LINE_GROW` up to `LINE_MOST` times, and fades in from `LINE_FADE` times less discharge (drawing only) | none: a thin line of a map, plain on a screen of either pixel ratio; a power steeper than the channel law's so a stream is a hair and the main river a few times wider; no wider than its bends are drawn from as near, so a line never swallows its bends | tuned, by eye |")
row('| `FLOOD` (5), `web/shaders/lib/land.wgsl`', "| `FLOOD` (5), `tape/src/ground/bends.rs`; `STATION_EXP` (0.26), `web/shaders/lib/rock.wgsl`; `BED_PX` (3), `web/shaders/land.wgsl` | none; none; pixels | a channel's bed is as wide as the channel law makes `FLOOD` times this month's discharge (and, for its bends, which never change, `FLOOD` × `TYPICAL_RUNOFF` a m² drained: `BED_RUNOFF`); this month's water is the bed's width times `FLOOD` to the power minus `STATION_EXP`, about two thirds; a bed under `BED_PX` pixels is drawn all water (drawing only) | the bankfull discharge, the flood of every year or two, is 2 to 10 times the mean flow in humid lands (Leopold and Maddock 1953; Wolman and Miller 1960; Dunne and Leopold 1978); at one place a channel's width grows as its discharge to the power 0.26 (at-a-station hydraulic geometry, Leopold and Maddock 1953) | anchored |")
row('| `BEND_WIDTHS` (11) and `BEND_HALF`', "| `BEND_WIDTHS` (11), `BELT_WIDTHS` (8), `WALL_DEPTHS` (4), `TURN_SHARE` (0.4), `BEND_MOST` (0.8 samples), `BENDS_FROM_M` (1 m), `REACH_SAMPLES` (2), `tape/src/ground/bends.rs`; `BEND_FROM` (12) and `BEND_TEXELS` (24 texels), `tape/src/ground/channels.rs` | bed widths; bed depths; share; samples; m; texels | a drawn channel's bends: their wavelength, by which a tile draws them (none under `BEND_FROM` texels, all from `BEND_TEXELS`); the half width of their belt where nothing holds it, held where the ground across the valley stands `WALL_DEPTHS` bed depths over the channel, within `TURN_SHARE` of the radius the valley's line turns on and `BEND_MOST` of a sample; none for a bed under `BENDS_FROM_M`; the slope and the floor read over `REACH_SAMPLES` up and down the channel (drawing only) | meander wavelength 7 to 15 widths, about 11 (Leopold and Wolman 1960); belts 4 to 20 widths across (Williams 1986); a bank a few times as high as the bed is deep is cut back by the bends, a higher one is the valley's wall | anchored |")
row('| `SMOOTH_SAMPLES` (3) and `SMOOTH_MOST`', "| `SMOOTH_SAMPLES` (6) and `SMOOTH_MOST` (1), `tape/src/ground/stems.rs` | samples | the samples up and down its stem a channel's drawn point is the mean of, and the most it moves from its sample's centre (drawing only) | none: six each way turn a stair of sides and corners into a smooth line at a 2 km scale bar; the valley is drawn about the line (`VALLEY_M`), so a sample's move keeps the line at its floor | tuned, by eye |")
tweak('| `VALLEY_FROM` (1 km²) and `VALLEY_M`', "`tape/src/ground/channels.rs`", "`CHORD_SHARE` (1/32), `tape/src/ground/valley.rs`")
tweak('| `VALLEY_FROM` (1 km²) and `VALLEY_M`', "| m²; m | the channels whose valley a tile draws, and how far across the ground is drawn toward their floor (drawing only)", "| m²; m; share | the channels whose valley a tile draws, how far across the ground is drawn toward their floor, and the shortest piece of a line a valley follows, as a share of that (drawing only)")
row('| `PHASE_SWING` (0.9 rad)', "| `STEPS` (24), `HEADING_MOST` (1.85 rad), `RADIUS_WIDTHS` (1.5 to 3.5), `REACH_SHARE` (0.5 to 1), `FAR_LEAST` (0.3), `SWELL_BENDS` (5), `SWELL_LEAST` (0.1), `WANDER` (0.5 over `WANDER_BENDS` 7), `ARC_WIDTHS` (3 to 24), `ADVANCE_WIDTHS` (2.5), `STRAIGHT_WIDTHS` (6), `ARC_HALVINGS` (14), `tape/src/ground/belt.rs`; `ALONG_WRAP_M` (128 m), `tape/src/ground/channels.rs` | rad; bed widths; share; half bends | the walk of a channel's bends from apex to apex: the steps of a half bend; the most its heading turns from the valley's line; an apex's radius, its reach as a share of the belt's half width and the least it lies across from the last; the belt's swell along the way and its middle's wander; a half bend's length, the least it carries the line down the valley, and a straight stretch's pieces; the length a texel's place along its channel is kept modulo (drawing only) | bends turn on 2 to 3 widths (Hickin and Nanson 1975) and their curvature falls evenly along them (Langbein and Leopold 1966); at these numbers 40 walks of 140 half bends have a sinuosity of 1.56, no two limbs within 1.2 widths and 17 within 2 | tuned, by eye |")
row('| `POOL_M` (60 to 300 m)', "| `BED_VARY` (0.22 over `BED_VARY_M` 32 and 8 m), `INNER_MOST` (0.8), `BEND_FULL` (0.4), `POOL_NARROW` (0.2), `RIFFLE_WIDE` (0.3), `web/shaders/lib/rock.wgsl`; `RAG_M` (9 and 2.6 m), `RAG_SHARE` (0.3), `RAG_MOST_M` (3 m), `STEEP_STONE` (0.12 to 0.5 m), `STREAK_W_M` (1.2 m), `STREAK_M` (8 m), `STREAK` (0.6), `WHITE_M` (4 m), `FOAM_STEEP` (0.55), `BAR_MOTTLE` (0.3), `BAR_PATCH_M` (2.5 and 0.6 m), `web/shaders/lib/river.wgsl`; `BAR_LIFT` (1.5), `BAR_SAND_STONE` (0.03 m), `REFLECT_STREAK` (0.25), `STONES_OUT` (1.2), `web/shaders/land.wgsl`; `RIVER_TRUE_E` (0.05 to 0.4 m), `web/shaders/lib/style.wgsl` | m; share | a bed's width varies by up to 22% along it and reaches no farther inside a bend than 0.8 of the radius its line turns on; in a full bend (curvature times bed width 0.4) the water is a pool 20% narrower against the outer bank over a bar inside, between bends a riffle 30% wider; its edges ragged; a steep reach moves stones of 0.12 to 0.5 m; bars of the bed's make washed, sand where no stone over 3 cm moves; streaks along the flow and white water on steep reaches (drawing only) | pools at the bends and riffles between them, five to seven widths apart (Leopold and Wolman 1957, 1960; Keller and Melhorn 1978) | tuned, by eye |")
open(p, 'w').write('\n'.join(lines))
